<?php
declare(strict_types=1);
require dirname(__DIR__,2).'/app/bootstrap.php';
require dirname(__DIR__,2).'/app/phase11.php';
require dirname(__DIR__,2).'/app/services/PeriodReviewService.php';
$user=require_auth();
$accountFilter=filter_var($_GET['account']??null,FILTER_VALIDATE_INT)?:null;$systemFilter=filter_var($_GET['system']??null,FILTER_VALIDATE_INT)?:null;
if($accountFilter!==null){$q=db()->prepare('SELECT id FROM accounts WHERE id=? AND user_id=?');$q->execute([$accountFilter,$user['id']]);if(!$q->fetchColumn())$accountFilter=null;}
if($systemFilter!==null){$q=db()->prepare('SELECT id FROM trading_systems WHERE id=? AND user_id=?');$q->execute([$systemFilter,$user['id']]);if(!$q->fetchColumn())$systemFilter=null;}
$stmt=db()->prepare('SELECT t.*,a.name account_name,a.currency,a.initial_balance,a.ideal_risk,ts.name system_name,st.name strategy_name FROM trades t JOIN accounts a ON a.id=t.account_id AND a.user_id=t.user_id LEFT JOIN trading_systems ts ON ts.id=t.trading_system_id AND ts.user_id=t.user_id LEFT JOIN strategies st ON st.id=t.strategy_id AND st.user_id=t.user_id WHERE t.user_id=?'.($accountFilter!==null?' AND t.account_id=?':'').($systemFilter!==null?' AND t.trading_system_id=?':'').' ORDER BY t.opened_at ASC,t.id ASC');$params=[$user['id']];if($accountFilter!==null)$params[]=$accountFilter;if($systemFilter!==null)$params[]=$systemFilter;$stmt->execute($params);$trades=$stmt->fetchAll();
$closed=[];foreach($trades as $t){$p=trade_pnl($t);if($p!==null){$t['pnl']=$p;$t['r']=$t['ideal_risk']>0?$p/(float)$t['ideal_risk']:null;$closed[]=$t;}}
$pnls=array_column($closed,'pnl');$count=count($pnls);$wins=count(array_filter($pnls,fn($p)=>$p>0));$grossWin=array_sum(array_filter($pnls,fn($p)=>$p>0));$grossLoss=abs(array_sum(array_filter($pnls,fn($p)=>$p<0)));$net=array_sum($pnls);$pf=$grossLoss>0?$grossWin/$grossLoss:null;$wr=$count?100*$wins/$count:null;$exp=$count?$net/$count:null;$largestWin=$pnls?max($pnls):null;$largestLoss=$pnls?min($pnls):null;
$equity=0;$equityLabels=[];$equityData=[];$balanceLabels=[];$balanceData=[];$rValues=[];$systems=[];$strategies=[];$months=[];foreach($closed as $t){$equity+=$t['pnl'];$equityLabels[]=(string)$t['id'];$equityData[]=round($equity,4);$balanceLabels[]=(string)$t['id'];$balanceData[]=round((float)$t['initial_balance']+$equity,4);if($t['r']!==null)$rValues[]=$t['r'];$month=date('Y-m',strtotime($t['closed_at']??$t['opened_at']));$months[$month]=($months[$month]??0)+$t['pnl'];$name=$t['system_name']??'Unassigned';$systems[$name]=($systems[$name]??0)+$t['pnl'];$strategy=$t['strategy_name']??'Unassigned';$strategies[$strategy]=($strategies[$strategy]??0)+$t['pnl'];}
$systemLabels=array_keys($systems);$systemData=array_map(fn($v)=>round($v,2),array_values($systems));$strategyLabels=array_keys($strategies);$strategyData=array_map(fn($v)=>round($v,2),array_values($strategies));$monthLabels=array_keys($months);$monthData=array_map(fn($v)=>round($v,2),array_values($months));$rBuckets=['<-2R'=>0,'-2R'=>0,'-1R'=>0,'0R'=>0,'1R'=>0,'2R'=>0,'3R+'=>0];foreach($rValues as $r){$k=$r<-2?'<-2R':($r<-1?'-2R':($r<0?'-1R':($r<1?'0R':($r<2?'1R':($r<3?'2R':'3R+')))));$rBuckets[$k]++;}
$calendarMonthRaw=trim((string)($_GET['month']??''));if(!preg_match('/^\d{4}-\d{2}$/',$calendarMonthRaw))$calendarMonthRaw=date('Y-m');$calendarMonth=DateTimeImmutable::createFromFormat('!Y-m-d',$calendarMonthRaw.'-01')?:new DateTimeImmutable('first day of this month');$goalPerformance=phase11_performance(db(),(int)$user['id'],$accountFilter,$systemFilter);$goalPerformance['monthStart']=$calendarMonth;$goalPerformance['calendar']=[];$days=(int)$calendarMonth->modify('first day of next month')->modify('-1 day')->format('d');for($d=1;$d<=$days;$d++){$day=$calendarMonth->setDate((int)$calendarMonth->format('Y'),(int)$calendarMonth->format('m'),$d);$goalPerformance['calendar'][$day->format('Y-m-d')]=phase11_period_pnl(db(),(int)$user['id'],$day->format('Y-m-d H:i:s'),$day->modify('+1 day')->format('Y-m-d H:i:s'),$accountFilter,$systemFilter);}
$weekdayWhere='t.user_id=? AND t.status="closed" AND t.exit_price IS NOT NULL';$weekdayParams=[(int)$user['id']];if($accountFilter!==null){$weekdayWhere.=' AND t.account_id=?';$weekdayParams[]=$accountFilter;}if($systemFilter!==null){$weekdayWhere.=' AND t.trading_system_id=?';$weekdayParams[]=$systemFilter;}$q=db()->prepare('SELECT DAYOFWEEK(t.closed_at) weekday_num,COUNT(*) trade_count,COALESCE(SUM('.phase11_pnl_expr().'),0) total_pnl,COALESCE(AVG('.phase11_pnl_expr().'),0) avg_pnl FROM trades t WHERE '.$weekdayWhere.' GROUP BY DAYOFWEEK(t.closed_at)');$q->execute($weekdayParams);$weekdayNames=[1=>'Sunday',2=>'Monday',3=>'Tuesday',4=>'Wednesday',5=>'Thursday',6=>'Friday',7=>'Saturday'];$weekdayRanking=[];foreach($q->fetchAll() as $r){$weekdayRanking[]=['day'=>$weekdayNames[(int)$r['weekday_num']],'trades'=>(int)$r['trade_count'],'total_pnl'=>(float)$r['total_pnl'],'avg_pnl'=>(float)$r['avg_pnl']];}$q=db()->prepare('SELECT DAYOFWEEK(t.closed_at) weekday_num,COALESCE(st.name,"Unassigned") strategy_name,COUNT(*) cnt FROM trades t LEFT JOIN strategies st ON st.id=t.strategy_id AND st.user_id=t.user_id WHERE '.$weekdayWhere.' GROUP BY DAYOFWEEK(t.closed_at),st.name ORDER BY weekday_num,cnt DESC,strategy_name');$q->execute($weekdayParams);$weekdayStrategy=[];foreach($q->fetchAll() as $r){$n=(int)$r['weekday_num'];if(!isset($weekdayStrategy[$n]))$weekdayStrategy[$n]=$r['strategy_name'];}foreach($weekdayRanking as &$r){$n=array_search($r['day'],$weekdayNames,true);$r['most_strategy']=$weekdayStrategy[$n]??'Unassigned';}$weekdayRanking=array_values($weekdayRanking);unset($r);usort($weekdayRanking,fn($a,$b)=>$b['avg_pnl']<=>$a['avg_pnl']);foreach($weekdayRanking as $i=>&$r)$r['rank']=$i+1;unset($r);$goalPerformance['weekdayRanking']=$weekdayRanking;
$timeWhere='t.user_id=? AND t.status="closed" AND t.exit_price IS NOT NULL';$timeParams=[(int)$user['id']];if($accountFilter!==null){$timeWhere.=' AND t.account_id=?';$timeParams[]=$accountFilter;}if($systemFilter!==null){$timeWhere.=' AND t.trading_system_id=?';$timeParams[]=$systemFilter;}$q=db()->prepare('SELECT HOUR(t.opened_at) hour_num,COUNT(*) trade_count,COALESCE(SUM('.phase11_pnl_expr().'),0) total_pnl,COALESCE(AVG('.phase11_pnl_expr().'),0) avg_pnl,COALESCE(AVG(CASE WHEN '.phase11_pnl_expr().' > 0 THEN 1 ELSE 0 END)*100,0) win_rate FROM trades t WHERE '.$timeWhere.' GROUP BY HOUR(t.opened_at) ORDER BY hour_num');$q->execute($timeParams);$timeRanking=[];foreach($q->fetchAll() as $r){$h=(int)$r['hour_num'];$timeRanking[]=['hour'=>$h,'label'=>sprintf('%02d:00–%02d:00',$h,($h+1)%24),'trades'=>(int)$r['trade_count'],'total_pnl'=>(float)$r['total_pnl'],'avg_pnl'=>(float)$r['avg_pnl'],'win_rate'=>(float)$r['win_rate']];}$q=db()->prepare('SELECT HOUR(t.opened_at) hour_num,COALESCE(st.name,"Unassigned") strategy_name,COUNT(*) cnt FROM trades t LEFT JOIN strategies st ON st.id=t.strategy_id AND st.user_id=t.user_id WHERE '.$timeWhere.' GROUP BY HOUR(t.opened_at),st.name ORDER BY hour_num,cnt DESC,strategy_name');$q->execute($timeParams);$timeStrategy=[];foreach($q->fetchAll() as $r){$h=(int)$r['hour_num'];if(!isset($timeStrategy[$h]))$timeStrategy[$h]=$r['strategy_name'];}foreach($timeRanking as &$r)$r['most_strategy']=$timeStrategy[$r['hour']]??'Unassigned';unset($r);usort($timeRanking,fn($a,$b)=>$b['avg_pnl']<=>$a['avg_pnl']);foreach($timeRanking as $i=>&$r)$r['rank']=$i+1;unset($r);$goalPerformance['timeRanking']=$timeRanking;
$goalPerformance['strategyPerformance']=[];foreach($strategies as $name=>$pnl){$goalPerformance['strategyPerformance'][]=['strategy'=>$name,'pnl'=>(float)$pnl];}usort($goalPerformance['strategyPerformance'],fn($a,$b)=>$b['pnl']<=>$a['pnl']);
if(isset($_GET['calendar_only'])&&$_GET['calendar_only']==='1'){require dirname(__DIR__,2).'/app/views/dashboard_calendar.php';exit;}
ob_start();render('dashboard_report',['title'=>'Dashboard','count'=>$count,'wr'=>$wr,'pf'=>$pf,'exp'=>$exp,'largestWin'=>$largestWin,'largestLoss'=>$largestLoss,'net'=>$net,'equityLabels'=>$equityLabels,'equityData'=>$equityData,'balanceLabels'=>$balanceLabels,'balanceData'=>$balanceData,'systemLabels'=>$systemLabels,'systemData'=>$systemData,'strategyLabels'=>$strategyLabels,'strategyData'=>$strategyData,'monthLabels'=>$monthLabels,'monthData'=>$monthData,'rLabels'=>array_keys($rBuckets),'rData'=>array_values($rBuckets),'goalPerformance'=>$goalPerformance,'selectedAccount'=>$accountFilter,'selectedSystem'=>$systemFilter]);$html=ob_get_clean();$goalPeriod=(string)($_GET['goal_period']??'day');if(!in_array($goalPeriod,['day','week','month','year'],true))$goalPeriod='day';ob_start();$uid=(int)$user['id'];$trend=\App\Services\PeriodReviewService::dashboardGoalTrend(db(),$uid,$goalPeriod,30);$labels=array_map(fn($r)=>$goalPeriod==='year'?date('Y',strtotime($r['period'])):date('M d',strtotime($r['period'])),$trend);$values=array_map(fn($r)=>(float)$r['achievement'],$trend);?><div class="card chart-card"><div class="section-heading"><div><h2>Review Goal Achievement</h2><div class="sub">Percentage of selected goals marked Hit in completed Post Reviews.</div></div><form method="get"><input type="hidden" name="account" value="<?=e((string)($accountFilter??''))?>"><input type="hidden" name="system" value="<?=e((string)($systemFilter??''))?>"><select name="goal_period" onchange="this.form.submit()"><option value="day" <?=$goalPeriod==='day'?'selected':''?>>Day</option><option value="week" <?=$goalPeriod==='week'?'selected':''?>>Week</option><option value="month" <?=$goalPeriod==='month'?'selected':''?>>Month</option><option value="year" <?=$goalPeriod==='year'?'selected':''?>>Year</option></select></form></div><canvas id="reviewGoalChart"></canvas></div><script src="https://cdn.jsdelivr.net/npm/chart.js"></script><script nonce="<?=e(csp_nonce())?>">new Chart(document.getElementById('reviewGoalChart'),{type:'line',data:{labels:<?=json_encode($labels)?>,datasets:[{label:'Goal Achievement',data:<?=json_encode($values)?>,tension:.25,fill:false}]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{display:false}},scales:{x:{grid:{display:false},ticks:{font:{size:8}}},y:{min:0,max:100,ticks:{callback:v=>v+'%',font:{size:8}}}}}});</script><?php $goalHtml=ob_get_clean();echo str_replace('</main>',$goalHtml.'</main>',$html);
